import{_ as o,b as i,c as s,g as l}from"./chunks/framework.86O3EbG5.js";const p=JSON.parse('{"title":"美国纽约摄影学院摄影教材","description":"","frontmatter":{"title":"美国纽约摄影学院摄影教材","subTitle":"培养摄影眼","author":"oasis","date":"2026-09-20T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/books/nyip-course/2.md","filePath":"articles/books/nyip-course/2.md"}'),r={name:"articles/books/nyip-course/2.md"};function e(n,t,a,_,d,c){return i(),s("div",null,[...t[0]||(t[0]=[l('<p>摄影眼可以理解为突出主题和主体的发现之眼：通过对场景的简化，用不同的技巧突出重点。</p><h2 id="突出重点的方法" tabindex="-1">突出重点的方法</h2><h3 id="主体在画幅中的位置" tabindex="-1">主体在画幅中的位置</h3><ol><li><strong>三分法</strong>：在画面中不同位置，可表达的感情是不一样的。书中列举伍迪·艾伦（Woody Allen）的例子，标出一种柔弱无助的感情——人物位于画面左侧三分之一处。</li></ol><h3 id="主体与周围物的关系" tabindex="-1">主体与周围物的关系</h3><ol><li><strong>大小关系</strong>：让主体看起来比周围物体大一些。</li><li><strong>制造焦点</strong>：通过搭建画框让主体突出。想象把手攥成空心拳，从大拇指这端向外看，空心拳变成了一个框定范围的装置，让观看者只能这样观看。</li><li><strong>光影对比</strong>。</li><li><strong>构造汇集线</strong>：实际是在构建透视线。</li><li><strong>通过选择突出焦点</strong>：除了景深之外，还可以选择性地安排主体关键位置的构图关系，例如将主体的面部放到黄金点。</li><li><strong>重复的主体</strong>。</li><li><strong>运动感</strong>。</li></ol><h3 id="后期处理" tabindex="-1">后期处理</h3><ol><li>要看取景是不是很近，导致主体部分被截断了。</li><li>背景是不是对表达主体造成了干扰，例如和主体很近似的色彩。</li><li>前景是不是畸变了。</li></ol>',8)])])}const h=o(r,[["render",e]]);export{p as __pageData,h as default};
